Servo dial;

void setup() {
  dial.attach(SERVO_PIN);
}

void loop() {
  int knob = analogRead(POT_PIN);
  int angle = map(knob, 0, ANALOG_MAX, 0, ___);
  dial.write(angle);
  delay(20);
}

